import os
import json
import uuid
import httpx
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import StreamingResponse, FileResponse
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from openai import OpenAI
from pydantic import BaseModel
from typing import Optional, List

app = FastAPI()

app.mount("/static", StaticFiles(directory="static"), name="static")

@app.get("/sw.js", include_in_schema=False)
async def serve_sw():
    return FileResponse("static/sw.js", media_type="application/javascript", headers={"Service-Worker-Allowed": "/"})

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

sessions: dict[str, list] = {}

EXA_TOOL = {
    "type": "function",
    "function": {
        "name": "exa_search",
        "description": (
            "Search the web for real-time information using Exa. "
            "Use this when the user needs current events, news, prices, recent research, "
            "live data, or any information that may have changed. "
            "You may call this multiple times per response with different queries. "
            "Only search when necessary—do not search for well-established facts you already know."
        ),
        "parameters": {
            "type": "object",
            "required": ["query"],
            "properties": {
                "query": {
                    "type": "string",
                    "description": "Natural language search query. Can be long and semantically rich."
                },
                "type": {
                    "type": "string",
                    "enum": ["neural", "fast", "auto", "deep", "deep-reasoning", "instant"],
                    "description": "Search method. auto=highest quality (default), fast=low latency, instant=lowest latency, deep=comprehensive web research."
                },
                "category": {
                    "type": "string",
                    "enum": ["company", "research paper", "news", "personal site", "financial report", "people"],
                    "description": "Focus on a specific content category."
                },
                "startPublishedDate": {
                    "type": "string",
                    "description": "ISO 8601 date — only return results published after this date (e.g. 2024-01-01)."
                },
                "endPublishedDate": {
                    "type": "string",
                    "description": "ISO 8601 date — only return results published before this date."
                },
                "includeDomains": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Restrict results to these domains only."
                },
                "excludeDomains": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Exclude results from these domains."
                },
                "userLocation": {
                    "type": "string",
                    "description": "Two-letter ISO country code to localize results (e.g. HU, US, DE)."
                },
                "summaryQuery": {
                    "type": "string",
                    "description": "Custom query to guide AI page summaries. Defaults to the main query."
                },
                "maxAgeHours": {
                    "type": "integer",
                    "description": "Max age of cached content in hours. 0=always livecrawl, -1=never livecrawl (cache only). Omit for default."
                },
                "additionalQueries": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Extra query variations for deep search type only."
                },
                "systemPrompt": {
                    "type": "string",
                    "description": "For deep search only: instructions guiding search planning and result synthesis."
                }
            }
        }
    }
}

SYSTEM_PROMPT = (
    "You are a helpful, knowledgeable assistant with access to real-time web search via the exa_search tool. "
    "Use it whenever the user needs current information, recent events, news, prices, or any data that may have changed recently. "
    "You may call it multiple times per response with different queries if needed. "
    "Only search when it is genuinely necessary—do not search for well-established facts you already know confidently. "
    "When writing code, always use fenced code blocks with the language identifier. "
    "Format mathematical expressions clearly. Be concise yet thorough."
)

class ImagePayload(BaseModel):
    data: str
    media_type: str = "image/jpeg"

class ChatRequest(BaseModel):
    session_id: Optional[str] = None
    message: str
    images: Optional[List[ImagePayload]] = None

def get_or_create_session(session_id: Optional[str]) -> tuple[str, list]:
    if session_id and session_id in sessions:
        return session_id, sessions[session_id]
    new_id = str(uuid.uuid4())
    sessions[new_id] = []
    return new_id, sessions[new_id]

def compress_image_base64(raw_b64: str, media_type: str) -> str:
    if "," in raw_b64:
        raw_b64 = raw_b64.split(",", 1)[1]
    return raw_b64

async def call_exa(params: dict) -> dict:
    exa_key = os.getenv("EXA_API_KEY", "")
    payload: dict = {
        "query": params["query"],
        "numResults": 100,
        "contents": {
            "summary": {
                "query": params.get("summaryQuery") or params["query"]
            }
        }
    }
    for field in ["type", "category", "startPublishedDate", "endPublishedDate",
                  "includeDomains", "excludeDomains", "userLocation",
                  "additionalQueries", "systemPrompt"]:
        val = params.get(field)
        if val is not None:
            payload[field] = val
    if params.get("maxAgeHours") is not None:
        payload["contents"]["maxAgeHours"] = params["maxAgeHours"]
    async with httpx.AsyncClient() as client:
        r = await client.post(
            "",
            headers={"x-api-key": exa_key, "Content-Type": "application/json"},
            json=payload,
            timeout=60.0,
        )
        r.raise_for_status()
        return r.json()

def format_exa_for_sse(exa_result: dict) -> list:
    results = exa_result.get("results", [])
    out = []
    for r in results[:12]:
        summary = ""
        raw_summary = r.get("summary")
        if isinstance(raw_summary, dict):
            summary = raw_summary.get("text", "")[:400]
        elif isinstance(raw_summary, str):
            summary = raw_summary[:400]
        out.append({
            "title": r.get("title", ""),
            "url": r.get("url", ""),
            "summary": summary,
            "published_date": r.get("publishedDate", "")
        })
    return out

def format_exa_for_model(exa_result: dict, query: str) -> str:
    results = exa_result.get("results", [])
    lines = [f'Web search results for: "{query}"', ""]
    for i, r in enumerate(results, 1):
        title = r.get("title", "")
        url = r.get("url", "")
        published = r.get("publishedDate", "")
        raw_summary = r.get("summary")
        summary = ""
        if isinstance(raw_summary, dict):
            summary = raw_summary.get("text", "")
        elif isinstance(raw_summary, str):
            summary = raw_summary
        lines.append(f"[{i}] {title}")
        lines.append(f"    URL: {url}")
        if published:
            lines.append(f"    Published: {published}")
        if summary:
            lines.append(f"    Summary: {summary}")
        lines.append("")
    return "\n".join(lines)

@app.get("/")
async def root():
    return FileResponse("index.html")

@app.get("/health")
async def health():
    return {"status": "ok"}

@app.post("/api/chat")
async def chat_endpoint(req: ChatRequest):
    sid, history = get_or_create_session(req.session_id)

    if req.images and len(req.images) > 0:
        content_parts: list = [{"type": "text", "text": req.message}]
        for img in req.images:
            b64 = compress_image_base64(img.data, img.media_type)
            content_parts.append({
                "type": "image_url",
                "image_url": {
                    "url": f"data:{img.media_type};base64,{b64}",
                    "detail": "high"
                }
            })
        user_msg = {"role": "user", "content": content_parts}
    else:
        user_msg = {"role": "user", "content": req.message}

    history.append(user_msg)
    entry_len = len(history)

    async def generate():
        client = OpenAI(
            api_key=os.getenv("FRIENDLI_TOKEN"),
            base_url="",
        )

        yield f"data: {json.dumps({'type': 'session', 'session_id': sid})}\n\n"

        full_content = ""
        reasoning_started = False
        reasoning_done = False

        try:
            while True:
                stream = client.chat.completions.create(
                    model="zai-org/GLM-5",
                    max_tokens=200000,
                    temperature=1,
                    top_p=0.95,
                    extra_body={
                        "parse_reasoning": True,
                        "chat_template_kwargs": {
                            "enable_thinking": True
                        }
                    },
                    tools=[EXA_TOOL],
                    tool_choice="auto",
                    messages=[{"role": "system", "content": SYSTEM_PROMPT}] + history,
                    stream=True,
                )

                tool_call_chunks: dict = {}
                finish_reason = None
                turn_content = ""

                for chunk in stream:
                    if not chunk.choices:
                        continue
                    choice = chunk.choices[0]
                    delta = choice.delta
                    if choice.finish_reason:
                        finish_reason = choice.finish_reason
                    if not delta:
                        continue

                    reasoning = getattr(delta, "reasoning_content", None)
                    content = getattr(delta, "content", None)

                    if reasoning:
                        if not reasoning_started:
                            reasoning_started = True
                            yield f"data: {json.dumps({'type': 'reasoning_start'})}\n\n"
                        yield f"data: {json.dumps({'type': 'reasoning', 'text': reasoning})}\n\n"

                    if content:
                        if reasoning_started and not reasoning_done:
                            reasoning_done = True
                            yield f"data: {json.dumps({'type': 'reasoning_end'})}\n\n"
                        turn_content += content
                        full_content += content
                        yield f"data: {json.dumps({'type': 'content', 'text': content})}\n\n"

                    if delta.tool_calls:
                        for tc in delta.tool_calls:
                            idx = tc.index
                            if idx not in tool_call_chunks:
                                tool_call_chunks[idx] = {"id": "", "name": "", "arguments": ""}
                            if tc.id:
                                tool_call_chunks[idx]["id"] = tc.id
                            if tc.function:
                                if tc.function.name:
                                    tool_call_chunks[idx]["name"] += tc.function.name
                                if tc.function.arguments:
                                    tool_call_chunks[idx]["arguments"] += tc.function.arguments

                if finish_reason == "tool_calls" and tool_call_chunks:
                    tool_calls_list = []
                    for idx in sorted(tool_call_chunks.keys()):
                        tc_data = tool_call_chunks[idx]
                        tool_calls_list.append({
                            "id": tc_data["id"],
                            "type": "function",
                            "function": {
                                "name": tc_data["name"],
                                "arguments": tc_data["arguments"]
                            }
                        })

                    history.append({
                        "role": "assistant",
                        "content": turn_content or "",
                        "tool_calls": tool_calls_list
                    })

                    for idx in sorted(tool_call_chunks.keys()):
                        tc_data = tool_call_chunks[idx]
                        tc_id = tc_data["id"]
                        try:
                            params = json.loads(tc_data["arguments"])
                        except Exception:
                            params = {}
                        query = params.get("query", "")
                        yield f"data: {json.dumps({'type': 'search_start', 'query': query, 'id': tc_id})}\n\n"
                        try:
                            exa_result = await call_exa(params)
                            sse_results = format_exa_for_sse(exa_result)
                            yield f"data: {json.dumps({'type': 'search_results', 'query': query, 'id': tc_id, 'results': sse_results})}\n\n"
                            model_content = format_exa_for_model(exa_result, query)
                        except Exception as ex:
                            yield f"data: {json.dumps({'type': 'search_error', 'query': query, 'id': tc_id, 'error': str(ex)})}\n\n"
                            model_content = f"Search for '{query}' failed: {str(ex)}"
                        history.append({
                            "role": "tool",
                            "tool_call_id": tc_id,
                            "content": model_content
                        })

                    yield f"data: {json.dumps({'type': 'search_done'})}\n\n"

                else:
                    history.append({"role": "assistant", "content": full_content})
                    yield f"data: {json.dumps({'type': 'done', 'session_id': sid})}\n\n"
                    break

        except Exception as e:
            del history[entry_len - 1:]
            yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}\n\n"

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        }
    )

@app.get("/api/session/{session_id}")
async def get_session(session_id: str):
    if session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    msgs = sessions[session_id]
    readable = []
    for m in msgs:
        if m.get("role") not in ("user", "assistant"):
            continue
        if "tool_calls" in m and not m.get("content"):
            continue
        if isinstance(m["content"], list):
            text = next((p["text"] for p in m["content"] if p.get("type") == "text"), "")
            has_image = any(p.get("type") == "image_url" for p in m["content"])
            readable.append({"role": m["role"], "content": text, "has_image": has_image})
        else:
            content = m.get("content") or ""
            if content:
                readable.append({"role": m["role"], "content": content, "has_image": False})
    return {"session_id": session_id, "messages": readable}

@app.delete("/api/session/{session_id}")
async def delete_session(session_id: str):
    if session_id in sessions:
        del sessions[session_id]
    return {"cleared": True}

@app.get("/api/sessions")
async def list_sessions():
    result = []
    for sid, msgs in sessions.items():
        user_msgs = [m for m in msgs if m.get("role") == "user"]
        if not user_msgs:
            continue
        first = user_msgs[0]
        preview = ""
        if isinstance(first["content"], list):
            preview = next((p["text"] for p in first["content"] if p.get("type") == "text"), "")
        else:
            preview = first["content"] or ""
        total = len([m for m in msgs if m.get("role") in ("user", "assistant") and not m.get("tool_calls")])
        result.append({"session_id": sid, "preview": preview[:80], "count": total})
    return {"sessions": result}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)

