class ImagePayload(BaseModel):
    data: str
    media_type: str = "image/jpeg"


class ChatRequest(BaseModel):
    session_id: Optional[str] = None
    message: str
    images: Optional[list[ImagePayload]] = None

    @field_validator("message")
    @classmethod
    def message_not_empty(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("Message cannot be empty")
        return v


def _evict_sessions() -> None:
    now = time.time()
    expired = [k for k, v in list(sessions.items()) if now - v["updated_at"] > SESSION_TTL]
    for k in expired:
        sessions.pop(k, None)
    overflow = len(sessions) - MAX_SESSIONS
    if overflow > 0:
        oldest = sorted(sessions.items(), key=lambda x: x[1]["updated_at"])[:overflow]
        for k, _ in oldest:
            sessions.pop(k, None)


async def get_or_create_session(session_id: Optional[str]) -> tuple[str, list]:
    async with sessions_lock:
        if session_id and session_id in sessions:
            sessions[session_id]["updated_at"] = time.time()
            return session_id, sessions[session_id]["messages"]
        _evict_sessions()
        sid = session_id if session_id else str(uuid.uuid4())
        now = time.time()
        sessions[sid] = {"messages": [], "created_at": now, "updated_at": now}
        return sid, sessions[sid]["messages"]


def strip_b64_prefix(raw_b64: str) -> str:
    if not raw_b64:
        raise ValueError("Empty base64 data")
    if "," in raw_b64:
        raw_b64 = raw_b64.split(",", 1)[1]
    if not raw_b64:
        raise ValueError("Empty base64 data after stripping prefix")
    return raw_b64


def build_api_messages(history: list) -> list:
    last_img_idx = -1
    for i, m in enumerate(history):
        if m.get("role") == "user" and isinstance(m.get("content"), list):
            if any(p.get("type") == "image_url" for p in m["content"]):
                last_img_idx = i
    result = []
    for i, m in enumerate(history):
        if m.get("role") == "user" and isinstance(m.get("content"), list) and i != last_img_idx:
            text_parts = [p.get("text", "") for p in m["content"] if p.get("type") == "text"]
            if text_parts:
                result.append({"role": "user", "content": text_parts[0]})
        else:
            result.append(m)
    if len(result) > MAX_HISTORY_MESSAGES:
        result = result[-MAX_HISTORY_MESSAGES:]
    return result


async def call_exa(params: dict) -> dict:
    if not _EXA_API_KEY:
        raise RuntimeError("EXA_API_KEY is not configured")
    query = params.get("query", "")
    if not query:
        raise ValueError("Search query is required")
    payload: dict = {
        "query": query,
        "numResults": 100,
        "contents": {
            "summary": {"query": params.get("summaryQuery") or query}
        },
    }
    if params.get("maxAgeHours") is not None:
        payload["contents"]["maxAgeHours"] = int(params["maxAgeHours"])
    search_type = params.get("type") or "auto"
    payload["type"] = search_type
    for field in ["category", "startPublishedDate", "endPublishedDate",
                  "includeDomains", "excludeDomains", "userLocation"]:
        val = params.get(field)
        if val is not None and val != "" and val != []:
            payload[field] = val
    if search_type in DEEP_SEARCH_TYPES:
        for field in ["additionalQueries", "systemPrompt"]:
            val = params.get(field)
            if val is not None and val != "" and val != []:
                payload[field] = val
    last_exc: Exception = RuntimeError("Exa call failed")
    for attempt in range(3):
        try:
            r = await _http_client.post(
                "",
                headers={"x-api-key": _EXA_API_KEY, "Content-Type": "application/json"},
                json=payload,
            )
            r.raise_for_status()
            return r.json()
        except (httpx.TransportError, httpx.TimeoutException) as exc:
            last_exc = exc
            if attempt < 2:
                await asyncio.sleep(1.5 ** attempt)
        except httpx.HTTPStatusError as exc:
            last_exc = exc
            if exc.response.status_code in (429, 500, 502, 503) and attempt < 2:
                await asyncio.sleep(1.5 ** attempt)
                continue
            raise
    raise last_exc


def format_exa_for_sse(exa_result: dict) -> list:
    results = exa_result.get("results", [])
    out = []
    for r in results[:12]:
        raw = r.get("summary")
        summary = ""
        if isinstance(raw, dict):
            summary = raw.get("text", "")[:400]
        elif isinstance(raw, str):
            summary = raw[:400]
        out.append({
            "title": (r.get("title") or "")[:120],
            "url": r.get("url", ""),
            "summary": summary,
            "published_date": r.get("publishedDate", ""),
        })
    return out


def format_exa_for_model(exa_result: dict, query: str) -> str:
    results = exa_result.get("results", [])
    seen_urls: set[str] = set()
    lines = [f'Web search results for: "{query}"', ""]
    count = 0
    for r in results:
        url = r.get("url", "")
        if url in seen_urls:
            continue
        seen_urls.add(url)
        count += 1
        title = (r.get("title") or "")[:120]
        published = r.get("publishedDate", "")
        raw = r.get("summary")
        summary = ""
        if isinstance(raw, dict):
            summary = raw.get("text", "")[:MAX_SUMMARY_CHARS]
        elif isinstance(raw, str):
            summary = raw[:MAX_SUMMARY_CHARS]
        lines.append(f"[{count}] {title}")
        lines.append(f"    URL: {url}")
        if published:
            lines.append(f"    Published: {published}")
        if summary:
            lines.append(f"    Summary: {summary}")
        lines.append("")
    return "\n".join(lines)


async def execute_tool(tc_data: dict) -> tuple[list[str], dict]:
    tc_id = tc_data.get("id") or f"tc_{uuid.uuid4().hex[:8]}"
    args_str = (tc_data.get("arguments") or "").strip()
    try:
        params = json.loads(args_str) if args_str else {}
    except Exception:
        params = {}
    query = params.get("query", "")
    if not query:
        ev = json.dumps({"type": "search_error", "query": "", "id": tc_id, "error": "Empty query"})
        return [ev], {"role": "tool", "tool_call_id": tc_id, "content": "Search failed: empty query"}
    events: list[str] = []
    events.append(json.dumps({"type": "search_start", "query": query, "id": tc_id}))
    try:
        exa_result = await call_exa(params)
        sse_results = format_exa_for_sse(exa_result)
        events.append(json.dumps({"type": "search_results", "query": query, "id": tc_id, "results": sse_results}))
        model_content = format_exa_for_model(exa_result, query)
    except Exception as exc:
        logger.error("Exa search failed for query %r: %s", query, exc)
        events.append(json.dumps({"type": "search_error", "query": query, "id": tc_id, "error": str(exc)}))
        model_content = f"Search for '{query}' failed: {exc}"
    return events, {"role": "tool", "tool_call_id": tc_id, "content": model_content}


